from evolving_agent.session import Deadline, ToolAgentSession
from evolving_agent.model import ModelReply, ToolCall
from evolving_agent.mcp_client import ToolOutcome

class Model:
    def __init__(self): self.calls=[]
    def reply(self, *, conversation, tools=()):
        self.calls.append((conversation, tools))
        n=len(self.calls)
        if n==1: return ModelReply('', (ToolCall('w','write_file','{"path":"output/x","content":"x"}'),), ({'type':'function_call','call_id':'w'},))
        if n==2: return ModelReply('', (ToolCall('v','run_command','{"command":["python","-m","compileall"]}'),), ({'type':'function_call','call_id':'v'},))
        if n==3: return ModelReply('draft with an overclaim', ())
        prompt=conversation[-1]['content']
        assert 'Latest directly observed source-mutation step: 1' in prompt, prompt
        assert 'Step 2 (after latest mutation): ["python", "-m", "compileall"] => [exit code 0]' in prompt, prompt
        assert tools == (), tools
        return ModelReply('corrected evidence-limited report', ())
class Tools:
    def call(self,name,args):
        return ToolOutcome(is_error=False,text='[exit code 0]\nverified' if name=='run_command' else 'written')

m=Model()
o=ToolAgentSession(m,Tools(),deadline=Deadline(10),max_steps=5,evidence_review=True).run(instructions='s',opening='u')
assert o.summary=='corrected evidence-limited report' and o.steps==4, o
assert 'reviewed against observed evidence' in o.reason, o
print('evidence review verified:',o.reason)

